<script setup lang="ts">
import MessageMailStatus from './MessageMailStatus.vue'
import type {Message} from '../../api/messages'
defineProps<{message:Message}>()
const labels:Record<string,string>={PRICE_ABOVE:'收盘价 >',PRICE_BELOW:'收盘价 <',DAILY_RISE:'日涨幅 >',DAILY_FALL:'日跌幅 >'}
function change(m:Message){const previous=Number(m.previousBackwardClose),current=Number(m.currentBackwardClose);return previous>0&&Number.isFinite(current)&&m.currentBackwardClose!==null?((current-previous)/previous*100).toFixed(4)+'%':'不可计算'}
</script>
<template><div class="evidence"><p><strong>{{labels[message.condition]||message.condition}} {{message.threshold}}{{message.condition.startsWith('PRICE_')?'元':'%'}}</strong><span>行情日期 {{message.tradeDate}}</span></p><p v-if="message.condition.startsWith('PRICE_')">触发收盘价：{{message.rawClose??'无数据'}} 元（未复权）</p><p v-else>复权口径日变化：{{change(message)}} <span>仅展示值四舍五入，触发判断使用原始精度。</span></p><p>来源采集时间：<time>{{message.capturedAt}}</time></p><details><summary>查看固定证据</summary><dl><dt>未复权收盘价</dt><dd>{{message.rawClose??'无数据'}}</dd><template v-if="message.condition.startsWith('DAILY_')"><dt>前一交易日后复权收盘价</dt><dd>{{message.previousBackwardClose??'无数据'}}</dd><dt>当日后复权收盘价</dt><dd>{{message.currentBackwardClose??'无数据'}}</dd></template><dt>定义</dt><dd>{{message.definition}}</dd><dt>证据ID</dt><dd>{{message.evidenceId}}</dd><dt>行情版本ID</dt><dd>{{message.rawVersionId}}</dd><dt>触发记录ID</dt><dd>{{message.triggerId}}</dd><dt>记录创建时间</dt><dd>{{message.createdAt}}</dd><dt>首次已读时间</dt><dd>{{message.readAt??'未读'}}</dd></dl><p>该次触发所需数据已核验，记录保留当时的条件与阈值，不表示当前行情仍满足条件。</p></details><MessageMailStatus :message-id="message.id"/></div></template>
<style scoped>.evidence{color:var(--muted);font-size:14px}.evidence strong{color:var(--ink)}.evidence p{margin:8px 0}.evidence span{display:inline-block;margin-left:12px}summary{cursor:pointer;color:var(--accent);padding:10px 0;min-height:44px}dl{display:grid;grid-template-columns:minmax(100px,190px) minmax(0,1fr);gap:8px 16px}dt{color:var(--muted)}dd{margin:0;color:var(--ink);overflow-wrap:anywhere}time{overflow-wrap:anywhere}@media(max-width:600px){.evidence span{display:block;margin-left:0}dl{grid-template-columns:1fr;gap:4px}dd{margin-bottom:8px}}</style>
